CREATE TABLE product_lines (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE suppliers (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, contact VARCHAR(150));
CREATE TABLE batches (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, batch_number VARCHAR(64) NOT NULL, numbering_epoch VARCHAR(32) NOT NULL, line_id BIGINT NOT NULL REFERENCES product_lines(id), production_date DATE NOT NULL, shift VARCHAR(16) NOT NULL CHECK(shift IN ('DAY','NIGHT')), status VARCHAR(16) NOT NULL CHECK(status IN ('PENDING','HOLD','RELEASED','REJECTED')), quantity_kg NUMERIC(12,3) NOT NULL CHECK(quantity_kg > 0));
CREATE INDEX idx_batches_search ON batches(production_date,line_id,status);
CREATE INDEX idx_batches_number ON batches(batch_number);
CREATE TABLE material_lots (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, supplier_id BIGINT NOT NULL REFERENCES suppliers(id), material_name VARCHAR(120) NOT NULL, lot_number VARCHAR(64) NOT NULL, received_kg NUMERIC(12,3) NOT NULL CHECK(received_kg > 0), received_date DATE NOT NULL, UNIQUE(supplier_id,lot_number));
CREATE TABLE batch_materials (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, batch_id BIGINT NOT NULL REFERENCES batches(id), material_lot_id BIGINT NOT NULL REFERENCES material_lots(id), used_kg NUMERIC(12,3) NOT NULL CHECK(used_kg > 0), UNIQUE(batch_id,material_lot_id));
CREATE TABLE machines (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, line_id BIGINT NOT NULL REFERENCES product_lines(id), code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL);
CREATE TABLE machine_runs (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, batch_id BIGINT NOT NULL REFERENCES batches(id), machine_id BIGINT NOT NULL REFERENCES machines(id), started_at TIMESTAMP WITH TIME ZONE NOT NULL, ended_at TIMESTAMP WITH TIME ZONE NOT NULL CHECK(ended_at >= started_at));
CREATE TABLE quality_tests (id BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1000) PRIMARY KEY, batch_id BIGINT NOT NULL REFERENCES batches(id), sampled_at TIMESTAMP WITH TIME ZONE NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL, result VARCHAR(16) NOT NULL CHECK(result IN ('PASS','FAIL','PENDING')), moisture_percent NUMERIC(5,2), note VARCHAR(300), CHECK(moisture_percent IS NULL OR (moisture_percent >= 0 AND moisture_percent <= 100)), CHECK(recorded_at >= sampled_at));
CREATE INDEX idx_quality_batch ON quality_tests(batch_id);

CREATE INDEX idx_materials_lot ON batch_materials(material_lot_id);
CREATE INDEX idx_runs_batch ON machine_runs(batch_id);
